// Package: ModelContextProtocol
using ModelContextProtocol.Server;

public class CustomerResource
{
    private readonly ICustomerRepository _repository;

    public CustomerResource(ICustomerRepository repository)
    {
        _repository = repository;
    }

    public IReadOnlyList<McpResource> ListResources()
    {
        return _repository.GetAllCustomers()
            .Select(c => new McpResource
            {
                Uri = $"customer://{c.Id}",
                Name = c.Name,
                Description = $"Customer record for {c.Name}",
                MimeType = "application/json"
            })
            .ToList();
    }

    public async Task<McpResourceContent> ReadResourceAsync(string uri, CancellationToken cancellationToken)
    {
        var customer = await _repository.GetByIdAsync(uri.Replace("customer://", ""), cancellationToken);
        return new McpResourceContent
        {
            Uri = uri,
            MimeType = "application/json",
            Text = JsonSerializer.Serialize(customer)
        };
    }
}
