// Package: ModelContextProtocol
using ModelContextProtocol.Server;

public record SupportTriagePrompt : McpPrompt
{
    public override string Name => "support_triage";
    public override string Description => "Summarize a support ticket and suggest next steps.";

    public override IReadOnlyList<McpPromptArgument> Arguments =>
    [
        new McpPromptArgument("ticket", "The support ticket text", required: true),
        new McpPromptArgument("customer_tier", "Customer tier such as free, pro, or enterprise", required: false)
    ];

    // Build the prompt template that the client will fill and send to the model
    public override string BuildPrompt(IReadOnlyDictionary<string, object?> arguments)
    {
        var tier = arguments.GetValueOrDefault("customer_tier")?.ToString() ?? "standard";
        var ticket = arguments.GetValueOrDefault("ticket")?.ToString() ?? "";
        return $"You are a support triage assistant.\nCustomer tier: {tier}\nTicket: {ticket}\nSummarize the issue and suggest next steps.";
    }
}
